async function init(){db=await openDB();await loadSave();state=migrate(state);document.addEventListener('click',onClick);document.addEventListener('change',onChange);document.addEventListener('input',ev=>{if(['strategy-low','strategy-high','strategy-qty'].includes(ev.target.id))updateStrategyPreview()});window.addEventListener('resize',()=>{const c=document.getElementById('stock-chart');if(c)drawChart(c,state.stocks[ticker].historical.slice(-chartRange),{candles:true});const e=document.getElementById('equity-chart');if(e)drawChart(e,state.history.slice(-150))});render();await persist()}window.STOCK_TYCOON_READY=init();
window.STOCK_TYCOON_TEST={initial,trade,advanceDay,equity,validate,getState:()=>state,setState:s=>state=s,processOrders,riskScore,shortOpen,shortCover,optionOpen,optionClose,settleDerivatives,marginReview,optionPrice,availableFunds,strategyPreview,strategyOpen,strategyClose,optionSellOpen,groupMetrics,optionCollateral,accountLocks,freeShares,portfolioGreeks,migrate,resetCareer,startTutorial,exitTutorial,getTutorial:()=>tutorialSession};
